function themeColor(value:string,kind:'text'|'background'|'border'='text'){const hex=value.toLowerCase();if(currentTheme==='platinum'&&kind==='background'&&hex==='#55b9ed')return '#8492bc';if(currentTheme==='platinum'&&kind==='background'&&['#d8f0fc','#e7f0ff','#e8f1ff','#e6f0ff','#edf4fc'].includes(hex))return '#dce2f1';const palette=themePalettes[currentTheme];if(currentTheme==='light')return value;if(kind==='text'){if(['#17191d','#17181b','#252a30','#252a2f','#28313a','#33363a'].includes(hex))return palette.ink;if(['#9298a1','#9299a2','#8d949d','#9aa1aa','#9aa0a7','#8e949c','#8e959e','#989ea6','#9199a3','#9ba2aa','#69727c','#707984','#7e8791','#444c55','#8f969e','#9ca2aa','#7f8790','#77808a','#84919c','#7a838c','#596875','#687682','#7c848e','#5f6871','#535b63','#647487'].includes(hex))return palette.muted;if(['#3478f6','#005bdb'].includes(hex))return palette.blue;return value;}if(kind==='border')return ['#edf0f3','#edf0f4','#e0e6eb','#eef0f3','#d8e5f3','#c6cbd2'].includes(hex)?palette.line:value;if(['#fff','#ffffff','#fffdf0'].includes(hex))return palette.surface;if(['#17191d','#17181b'].includes(hex))return palette.button;if(['#f2f4f7','#f2f5f8','#f3f5f7','#f5f6f9','#f7f8fa','#f1f4f7','#f1f2f5','#f2f3f5','#eff0f3','#edf0f4','#edf0f3','#e8ebef','#f6f7f9','#f3f4f6','#f0f1f3','#f5f8fb','#f6f8fa','#f8f9fa','#f4f6f8','#eef1f5'].includes(hex))return palette.surfaceAlt;if(hex==='#d8f0fc')return currentTheme==='cyberpunk'?'#efcf28':'#1b3346';if(hex==='#3478f6')return palette.blue;return value;}
