function Icon({name,color=colors.ink,size=21,strokeWidth=2}:{name:string;color?:string;size?:number;strokeWidth?:number}) { const common={stroke:color,strokeWidth,strokeLinecap:'round' as const,strokeLinejoin:'round' as const,fill:'none' as const}; return <Svg width={size} height={size} viewBox="0 0 24 24">{name==='home'?<><Path {...common} d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/><Path {...common} d="M9 21v-7h6v7"/></>:name==='train'?<><Path {...common} d="M4 10v4m4-7v10m8-10v10m4-7v4M8 12h8"/></>:name==='progress'?<><Rect {...common} x="4" y="12" width="4" height="8" rx="1"/><Rect {...common} x="10" y="8" width="4" height="12" rx="1"/><Rect {...common} x="16" y="4" width="4" height="16" rx="1"/></>:name==='profile'?<><Circle {...common} cx="12" cy="8" r="4"/><Path {...common} d="M4 21a8 8 0 0 1 16 0"/></>:name==='search'?<><Circle {...common} cx="10.8" cy="10.8" r="6.5"/><Path {...common} d="m16 16 4 4"/></>:name==='plus'?<Path {...common} d="M12 5v14M5 12h14"/>:name==='down'?<Path {...common} d="M12 5v14m-7-7 7 7 7-7"/>:name==='up'?<Path {...common} d="M12 19V5m-7 7 7-7 7 7"/>:name==='rest'?<><Path {...common} d="M20.5 14.3A8.5 8.5 0 0 1 9.7 3.5 8.5 8.5 0 1 0 20.5 14.3Z"/></>:name==='edit'?<Path {...common} d="m15 5 4 4M4 20l4-.8L19.3 7.9a2.1 2.1 0 0 0-3-3L5 16.2z"/>:name==='eye'?<><Path {...common} d="M2.5 12s3.4-6 9.5-6 9.5 6 9.5 6-3.4 6-9.5 6-9.5-6-9.5-6Z"/><Circle {...common} cx="12" cy="12" r="2.7"/></>:name==='eyeOff'?<><Path {...common} d="m3 3 18 18M10.6 6.2A10.7 10.7 0 0 1 12 6c6.1 0 9.5 6 9.5 6a15 15 0 0 1-3.1 3.6M6.2 6.2C3.8 7.8 2.5 12 2.5 12s3.4 6 9.5 6c.9 0 1.8-.2 2.6-.4"/><Path {...common} d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></>:name==='trash'?<><Path {...common} d="M4 7h16M10 11v6m4-6v6M5 7l1 13h12l1-13M9 7V4h6v3"/></>:name==='calendar'?<><Rect {...common} x="3" y="5" width="18" height="16" rx="2"/><Path {...common} d="M16 3v4M8 3v4M3 10h18"/></>:name==='chevron'?<Path {...common} d="m6 9 6 6 6-6"/>:name==='arrowRight'?<Path {...common} d="M5 12h14m-6-6 6 6-6 6"/>:name==='return'?<Path {...common} d="M9 7 4 12l5 5M4 12h10a6 6 0 0 1 6 6"/>:name==='swap'?<><Path {...common} d="M4 8h13m-3-3 3 3-3 3"/><Path {...common} d="M20 16H7m3-3-3 3 3 3"/></>:name==='reset'?<><Path {...common} d="M20 11a8 8 0 1 0 1.2 4.8"/><Path {...common} d="M20 4v7h-7"/></>:name==='skip'?<><Path {...common} d="m5 5 7 7-7 7"/><Path {...common} d="m12 5 7 7-7 7"/></>:name==='minimize'?<Path {...common} d="M5 12h14"/>:name==='coach'?<><Path {...common} d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1"/><Circle {...common} cx="12" cy="12" r="3"/></>:<Path {...common} d="m5 12 4 4L19 6"/>}</Svg> }

function ScrollCue({visible,atBottom,onPress,bottom=22}:{visible:boolean;atBottom:boolean;onPress:()=>void;bottom?:number}){const switchProgress=useRef(new Animated.Value(atBottom?1:0)).current;const scale=useRef(new Animated.Value(1)).current;useEffect(()=>{Animated.parallel([Animated.timing(switchProgress,{toValue:atBottom?1:0,duration:220,useNativeDriver:true}),Animated.sequence([Animated.timing(scale,{toValue:.92,duration:90,useNativeDriver:true}),Animated.spring(scale,{toValue:1,useNativeDriver:true,damping:13,stiffness:230})])]).start();},[atBottom,scale,switchProgress]);if(!visible)return null;const arrowRotation=switchProgress.interpolate({inputRange:[0,1],outputRange:['0deg','180deg']});return <Animated.View style={[styles.scrollCue,{bottom,transform:[{scale}]}]}><Pressable accessibilityRole="button" accessibilityLabel={atBottom?'Scroll back to top':'Scroll down for more exercises'} onPress={onPress} style={styles.scrollCueButton}><Animated.View style={{transform:[{rotate:arrowRotation}]}}><Icon name="down" color="#fff" size={24}/></Animated.View></Pressable></Animated.View>; }

export default function HomeScreen(){
 const {isLoading,isAuthenticated,user}=useBackendAuth();
 const billing=useBilling(isAuthenticated?user?.uid??null:null);
 const [minimumLoadingElapsed,setMinimumLoadingElapsed]=useState(false);
 const [authWaitExpired,setAuthWaitExpired]=useState(false);
 const [billingWaitExpired,setBillingWaitExpired]=useState(false);
 const [entryRoute,setEntryRoute]=useState<'auth'|'onboarding'|'returningLoading'|'newUserLoading'|'app'|null>(null);
 const [welcomeMessage,setWelcomeMessage]=useState<string|null>(null);
 const finishEntryLoading=useCallback(()=>setEntryRoute('app'),[]);
 useEffect(()=>{
  const timer=setTimeout(()=>setMinimumLoadingElapsed(true),3000);
  return()=>clearTimeout(timer);
 },[]);
 useEffect(()=>{
  if(!isLoading){setAuthWaitExpired(false);return;}
  const timer=setTimeout(()=>setAuthWaitExpired(true),15000);
  return()=>clearTimeout(timer);
 },[isLoading]);
 useEffect(()=>{
  setBillingWaitExpired(false);
  if(!isAuthenticated||billing.status||billing.error)return;
  const timer=setTimeout(()=>setBillingWaitExpired(true),5000);
  return()=>clearTimeout(timer);
 },[isAuthenticated,user?.uid,billing.status,billing.error]);
 useEffect(()=>{
  if(!isAuthenticated||entryRoute!==null)return;
  let alive=true;
  Promise.all([AsyncStorage.getItem('repday.onboardingOwner'),AsyncStorage.getItem('repday.onboardingComplete')]).then(([owner,complete])=>{if(alive)setEntryRoute(owner===user?.uid&&complete!=='true'?'onboarding':'app');}).catch(()=>{if(alive)setEntryRoute('app');});
  return()=>{alive=false;};
 },[isAuthenticated,user?.uid,entryRoute]);
 if(isLoading&&authWaitExpired)return <StartupRecoveryScreen message="Repday is taking longer than expected to connect. Check your internet connection, then reload the app."/>;
 if(isLoading||!minimumLoadingElapsed||(isAuthenticated&&!billing.status&&!billing.error&&!billingWaitExpired))return <LoadingScreen status={billing.status}/>;
 const accountName=user?.displayName?.trim()||user?.email?.split('@')[0]?.replace(/[._-]+/g,' ').replace(/\b\w/g,letter=>letter.toUpperCase())||'there';
 if(!isAuthenticated)return <SignInScreen onAuthAttempt={()=>setEntryRoute('auth')} onExistingUser={name=>{setWelcomeMessage(`Welcome back, ${name||accountName}!`);setEntryRoute('returningLoading');}} onNewUser={name=>{setWelcomeMessage(`Welcome, ${name||accountName}!`);setEntryRoute('onboarding');}}/>;
 if(entryRoute===null)return <LoadingScreen status={billing.status}/>;
 if(entryRoute==='auth'||entryRoute==='onboarding')return <SignInScreen mode={entryRoute} onAuthAttempt={()=>setEntryRoute('auth')} onExistingUser={name=>{setWelcomeMessage(`Welcome back, ${name||accountName}!`);setEntryRoute('returningLoading');}} onNewUser={name=>{setWelcomeMessage(`Welcome, ${name||accountName}!`);setEntryRoute('onboarding');}} onOnboardingComplete={()=>setEntryRoute('newUserLoading')}/>;
 if(entryRoute==='returningLoading'||entryRoute==='newUserLoading')return <LoadingScreen status={billing.status} onComplete={finishEntryLoading}/>;
 return <WorkoutApp welcomeMessage={welcomeMessage} billing={billing}/>;
}

function StartupRecoveryScreen({message,onRetry}:{message:string;onRetry?:()=>void}){
 const retry=async()=>{
  if(onRetry){onRetry();return;}
  try{if(Platform.OS==='web'&&typeof window!=='undefined')window.location.reload();else await Updates.reloadAsync();}catch{}
 };
 return <SafeAreaView style={{flex:1,backgroundColor:'#fff',justifyContent:'center',alignItems:'center',padding:28}}><Text style={{fontSize:25,fontWeight:'800',color:'#17191d',textAlign:'center'}}>Still loading?</Text><Text style={{fontSize:16,lineHeight:24,color:'#69727c',textAlign:'center',marginTop:10,maxWidth:360}}>{message}</Text><Pressable accessibilityRole="button" onPress={retry} style={{marginTop:22,backgroundColor:'#3478f6',borderRadius:18,paddingHorizontal:26,paddingVertical:14}}><Text style={{fontSize:16,fontWeight:'800',color:'#fff'}}>Try again</Text></Pressable></SafeAreaView>;
}

function LoadingScreen({onComplete,status}:{onComplete?:()=>void;status:BillingStatus|null}){
 useWhiteLoadingChrome();
 const showPlus=!!status?.premium&&(status.accessSource==='manual'||(typeof status.paidUntil==='number'&&status.paidUntil>Date.now()));
 const [frame,setFrame]=useState(0);
 const frameWidth=Math.min((Dimensions.get('window').width-32)*.75,345);
 const spriteScale=frameWidth/368;
 const frameHeight=496*spriteScale;
 const column=frame%4;
 const row=Math.floor(frame/4);
 useEffect(()=>{
  const timer=setInterval(()=>setFrame(current=>(current+1)%8),145);
  return()=>clearInterval(timer);
 },[]);
 useEffect(()=>{
  if(!onComplete)return;
  const complete=setTimeout(onComplete,3000);
  return()=>clearTimeout(complete);
 },[onComplete]);
 return <SafeAreaView style={{flex:1,backgroundColor:'#fff',alignItems:'center',justifyContent:'center'}}><StatusBar style="dark"/>
  <View accessibilityRole="image" accessibilityLabel={showPlus?'Repday Plus loading animation':'Repday loading animation'} style={{width:frameWidth,height:frameHeight}}>
   <View style={{width:frameWidth,height:frameHeight,overflow:'hidden'}}>
    <ExpoImage source={showPlus?require('../assets/repday-loading-sprite-plus.png'):require('../assets/repday-loading-sprite.png')} contentFit="fill" cachePolicy="memory" style={{position:'absolute',width:1536*spriteScale,height:1024*spriteScale,left:-(column*384+8)*spriteScale,top:-(row*512+8)*spriteScale}}/>
   </View>
   {showPlus&&<View testID="loading-plus-badge" pointerEvents="none" style={{position:'absolute',right:8*spriteScale,top:22*spriteScale,backgroundColor:PLUS_GOLD.background,borderColor:'#fff',borderWidth:2,borderRadius:12,paddingHorizontal:9,paddingVertical:4,shadowColor:PLUS_GOLD.border,shadowOpacity:.2,shadowRadius:4,shadowOffset:{width:0,height:2}}}><Text style={{color:PLUS_GOLD.ink,fontSize:11,fontWeight:'900',letterSpacing:1}}>PLUS</Text></View>}
  </View>
 </SafeAreaView>;
}

