   const splitAdditions=working.moves.filter(move=>move.activeSessionOnly&&move.addToSplitOnFinish).map(({activeSessionOnly:_local,addToSplitOnFinish:_optIn,...move})=>({...move,sets:move.sets.map(({addedDuringWorkout:_added,...set})=>({...set,done:false}))}));
