   const savedSession:Session={...working,moves:working.moves.map(({activeSessionOnly:_local,addToSplitOnFinish:_optIn,...move})=>({...move,sets:move.sets.map(({addedDuringWorkout:_added,...set})=>({...set}))}))};setWorking(savedSession);
   const record:WorkoutRecord={id:String(completedAt),name:savedSession.name,startedAt:activeWorkout?.startedAt??completedAt-seconds*1000,duration:seconds,volume:savedSession.moves.reduce((n,m)=>n+m.sets.filter(set=>set.done).reduce((a,set)=>a+(Number(set.weight)||0)*(Number(set.reps)||0),0),0),sets:savedSession.moves.reduce((n,m)=>n+m.sets.filter(set=>set.done).length,0),exercises:savedSession.moves.filter(move=>move.sets.some(set=>set.done)).length,session:savedSession};setHistory(history=>[record,...history]);if(isAuthenticated&&remoteSettings?.userId&&cloudOwnerId===remoteSettings.userId)upsertHistoryItemCloud({item:record}).catch(()=>{});
